SELECT method, CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, COUNT(DISTINCT amount) AS unique_methods, ROUND((100 * SUM(CASE WHEN method = 'card' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_card, SUM(amount) AS total_amount FROM payments GROUP BY method, CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END HAVING unique_methods > 3 ORDER BY paid_cohort DESC, method LIMIT 5;
